using System;using System.IO;using System.Text;using System.Diagnostics;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;
public class GameProcess {public int Id;public string Path;public long Created;}
public static class GameTools {
 [DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr OpenProcess(uint access,bool inherit,int pid);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool QueryFullProcessImageName(IntPtr process,uint flags,StringBuilder path,ref int length);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetProcessTimes(IntPtr process,out long created,out long exited,out long kernel,out long user);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool TerminateProcess(IntPtr process,uint code);
 [DllImport("kernel32.dll")]static extern uint WaitForSingleObject(IntPtr handle,uint milliseconds);
 [DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr handle);
 public static bool Within(string root,string file){try{return Path.GetFullPath(file).StartsWith(Path.GetFullPath(root).TrimEnd(new char[]{Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar})+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);}catch{return false;}}
 static GameProcess Inspect(IntPtr handle,int id){var path=new StringBuilder(32768);int size=path.Capacity;long created,exit,kernel,user;if(!QueryFullProcessImageName(handle,0,path,ref size)||!GetProcessTimes(handle,out created,out exit,out kernel,out user))return null;return new GameProcess{Id=id,Path=path.ToString(),Created=created};}
 public static List<GameProcess> Processes(string root){var result=new List<GameProcess>();int own=Process.GetCurrentProcess().Id;foreach(var p in Process.GetProcesses())using(p){if(p.Id==own)continue;IntPtr handle=OpenProcess(0x1000,false,p.Id);if(handle==IntPtr.Zero)continue;try{var info=Inspect(handle,p.Id);if(info!=null&&Within(root,info.Path))result.Add(info);}finally{CloseHandle(handle);}}return result;}
 public static bool SameProcess(string root,GameProcess planned,GameProcess current){return current!=null&&planned.Id==current.Id&&planned.Created==current.Created&&string.Equals(planned.Path,current.Path,StringComparison.OrdinalIgnoreCase)&&Within(root,current.Path);}
 public static void ForceClose(string root,IEnumerable<GameProcess> planned,Action<string> log){foreach(var process in planned){IntPtr handle=OpenProcess(0x1000|0x100000|1,false,process.Id);if(handle==IntPtr.Zero){int error=Marshal.GetLastWin32Error();using(var p=TryProcess(process.Id)){if(p==null)continue;}throw new System.ComponentModel.Win32Exception(error,"Cannot close game process "+process.Id);}try{var current=Inspect(handle,process.Id);if(!SameProcess(root,process,current)){log("Process changed; skipped PID "+process.Id);continue;}if(!TerminateProcess(handle,1))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());if(WaitForSingleObject(handle,10000)!=0)throw new Exception("Timed out closing game process "+process.Id);log("Closed game process: "+process.Id+" | "+process.Path);}finally{CloseHandle(handle);}}}
 static Process TryProcess(int id){try{return Process.GetProcessById(id);}catch(ArgumentException){return null;}}
 public static string UninstallArgument(string appId){uint id;if(!uint.TryParse(appId,out id)||id==0)throw new Exception("Invalid installed Steam AppID");return "steam://uninstall/"+id;}
 public static void Uninstall(string steam,Game game){string argument=UninstallArgument(game.AppId);if(!Core.IsSteamRoot(steam))throw new Exception("Steam installation unavailable");Process.Start(new ProcessStartInfo(Core.Inside(steam,"steam.exe"),argument){UseShellExecute=false});}
 static bool EqualRoot(string a,string b){return Path.GetFullPath(a).TrimEnd(new char[]{Path.DirectorySeparatorChar}).Equals(Path.GetFullPath(b).TrimEnd(new char[]{Path.DirectorySeparatorChar}),StringComparison.OrdinalIgnoreCase);}
 static void DeleteKnown(string root,string relative,string expected,Action<string> log){string file=Core.Inside(root,relative);if(!File.Exists(file))return;if(expected!=null&&Core.Hash(file)!=expected){log("Kept changed backup: "+file);return;}File.Delete(file);log("Removed Fixer file: "+file);string dir=Path.GetDirectoryName(file);while(Within(root,dir)&&Directory.Exists(dir)&&Directory.GetFileSystemEntries(dir).Length==0){Directory.Delete(dir);dir=Path.GetDirectoryName(dir);}}
 public static void CleanArchives(string root,Action<string> log){string folder=Core.Inside(root,"LegacySteamFixer-Auto");if(!Directory.Exists(folder))return;foreach(string directory in Directory.GetDirectories(folder,"archive-*")){string name=Path.GetFileName(directory);Guid guid;if(!Guid.TryParseExact(name.Substring(8),"N",out guid))continue;string archive=Core.Inside(root,"LegacySteamFixer-Auto/"+name),record=Core.Inside(archive,"state.json");if(!File.Exists(record))continue;AutoState state;try{state=new JavaScriptSerializer().Deserialize<AutoState>(File.ReadAllText(record));if(state==null||state.Version!="0.3.0-test1"||!EqualRoot(state.Root,root)||state.Files==null||state.Files.Count==0)continue;}catch{log("Kept unrecognized archive: "+archive);continue;}
   var allowed=new HashSet<string>(StringComparer.OrdinalIgnoreCase);allowed.Add(record);bool valid=true;foreach(var f in state.Files){string backup=Core.Inside(archive,f.Backup),target=Core.Inside(root,f.Path);allowed.Add(backup);if(!File.Exists(target)||Core.Hash(target)!=f.OriginalHash||File.Exists(backup)&&Core.Hash(backup)!=f.OriginalHash){valid=false;break;}}if(!valid){log("Kept archive whose originals cannot be verified: "+archive);continue;}
   var files=KnownFiles(archive);foreach(string file in files)if(!allowed.Contains(file))valid=false;if(!valid){log("Kept archive containing additional files: "+archive);continue;}foreach(var f in state.Files)DeleteKnown(archive,f.Backup,f.OriginalHash,log);DeleteKnown(archive,"state.json",null,log);if(Directory.Exists(archive)&&Directory.GetFileSystemEntries(archive).Length==0)Directory.Delete(archive);
  }if(Directory.Exists(folder)&&Directory.GetFileSystemEntries(folder).Length==0)Directory.Delete(folder);}
 static List<string> KnownFiles(string root){var files=new List<string>();foreach(string path in Directory.GetFileSystemEntries(root)){if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new Exception("Reparse point in cleanup folder: "+path);if(Directory.Exists(path))files.AddRange(KnownFiles(path));else files.Add(path);}return files;}
 public static void Cleanup(Game game,Action<string> log){if(Processes(game.Root).Count>0)throw new Exception("Close game processes before clearing patches");if((File.GetAttributes(game.Root)&FileAttributes.ReparsePoint)!=0)throw new Exception("Reparse game root rejected");if(AutoBridge.HasState(game.Root))AutoBridge.Restore(game.Root,log);Core.Inspect(game);if(game.Module!=null){bool dedicated=false;foreach(var target in game.Module.Targets){string file=Core.Inside(game.Root,target.Path);if(File.Exists(Core.Inside(game.Root,target.Backup))||File.Exists(file)&&Core.Hash(file)==target.Patched)dedicated=true;}if(dedicated){if(game.Status=="Patched")Core.Apply(game,true,log);else if(game.Status!="Ready")throw new Exception("Cannot safely restore this game's dedicated repair: "+game.Detail);foreach(var target in game.Module.Targets){if(Core.Hash(Core.Inside(game.Root,target.Path))!=target.Original)throw new Exception("Original game file not verified: "+target.Path);}foreach(var target in game.Module.Targets){DeleteKnown(game.Root,target.Backup,target.Original,log);DeleteKnown(game.Root,"LegacySteam-Test1-Backup/"+target.Path,target.Original,log);}}}
  CleanArchives(game.Root,log);
  if(Directory.Exists(LaunchProfiles.Folder))foreach(string path in Directory.GetFiles(LaunchProfiles.Folder,"*.json")){LaunchProfile profile;try{profile=LaunchProfiles.Load(Path.GetFileNameWithoutExtension(path));}catch{log("Kept unrecognized profile: "+path);continue;}if(!EqualRoot(profile.Root,game.Root))continue;foreach(string file in new[]{"launch.txt","LegacySteam-Injector.log"})DeleteKnown(LaunchProfiles.Folder,profile.Id+"/"+file,null,log);foreach(string name in new[]{"LegacySteam-Unity.log","LegacySteam-InjectBridge.log"})DeleteKnown(game.Root,Path.Combine(Path.GetDirectoryName(profile.Exe)??"",name),null,log);LaunchProfiles.Remove(profile);}
  foreach(string file in new[]{"LegacySteam-Unity.log","LegacySteam-InjectBridge.log"})DeleteKnown(game.Root,file,null,log);log("Fixer cleanup completed. Saves, mods and unrelated files were retained.");
 }
}
